theme.css:
/* theme: Yield at the Brink | The 10-year near 5% and oil above $100 set a tense stage where every market move carries weight. */
.diary-page {
  --paper: #fdfcf9;
  --paper-alt: #f5f2e8;
  --ink: #1a1a1e;
  --ink-soft: #3f3f47;
  --muted: #656570;
  --accent: #b23c1e;
  --accent-ink: #ffffff;
  --rule: #e3e0d6;
  --font-display: var(--ff-fraunces), Georgia, serif;
  --font-body: var(--ff-newsreader), Georgia, serif;
  --font-ui: var(--ff-inter), system-ui, sans-serif;
}

@media (prefers-color-scheme: dark) {
  .diary-page {
    --paper: #131316;
    --paper-alt: #1c1c21;
    --ink: #f4f3ee;
    --ink-soft: #d4d3cd;
    --muted: #a09f98;
    --accent: #e86a4a;
    --accent-ink: #1a0e08;
    --rule: #2f2f36;
  }
}

.diary-page .diary-hero {
  position: relative;
  overflow: hidden;
}

.diary-page .diary-hero::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 4px;
  background: linear-gradient(90deg, var(--accent) 0%, var(--accent) 68%, var(--ink) 68%, var(--ink) 68.5%, var(--accent) 68.5%, var(--accent) 100%);
}

.diary-page .diary-hero-inner {
  position: relative;
  padding-top: 2.5rem;
}

.diary-page .diary-kicker {
  letter-spacing: 0.22em;
  font-weight: 700;
}

.diary-page .diary-title {
  max-width: 24ch;
  font-weight: 700;
  letter-spacing: -0.03em;
}

.diary-page .diary-summary {
  max-width: 48rem;
  font-size: clamp(1.1rem, 1.9vw, 1.35rem);
  line-height: 1.7;
}

.diary-page .diary-theme-note {
  margin-top: 2rem;
  font-size: 0.9rem;
  padding-left: 0.75rem;
  border-left: 2px solid var(--accent);
}

.diary-page .diary-theme-name {
  background: transparent;
  color: var(--accent);
  padding: 0;
  border-radius: 0;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  font-size: 0.78rem;
  margin-right: 0.6rem;
}

.diary-page .diary-body {
  padding-top: 1rem;
}

.diary-page .diary-toc {
  background: color-mix(in srgb, var(--paper) 92%, var(--accent) 8%);
}

@media (min-width: 1024px) {
  .diary-page .diary-toc {
    background: none;
  }
}

.diary-page .diary-toc-list {
  border-left-color: color-mix(in srgb, var(--rule) 60%, var(--accent) 40%);
}

.diary-page .diary-toc-link {
  font-weight: 500;
}

.diary-page .diary-toc-link.is-active {
  color: var(--ink);
  font-weight: 700;
}

.diary-page .diary-toc-number {
  font-family: var(--ff-plex-mono), ui-monospace, monospace;
  font-size: 0.7rem;
  font-weight: 600;
  letter-spacing: 0.02em;
}

.diary-page .diary-section {
  position: relative;
}

.diary-page .diary-section::after {
  content: "";
  position: absolute;
  left: 0;
  bottom: 0;
  width: 100%;
  height: 1px;
  background: linear-gradient(90deg, var(--accent) 0%, var(--accent) 96px, var(--rule) 96px, var(--rule) 100%);
}

.diary-page .diary-section:last-of-type::after {
  display: none;
}

.diary-page .diary-section-head {
  margin-bottom: 2rem;
  padding-bottom: 1rem;
  border-bottom: 1px solid var(--rule);
}

.diary-page .diary-section-number {
  font-family: var(--ff-plex-mono), ui-monospace, monospace;
  font-size: 0.85rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  color: var(--accent);
  margin-right: 0.25rem;
}

.diary-page .diary-section-title {
  font-weight: 650;
  letter-spacing: -0.02em;
}

.diary-page .diary-prose {
  font-size: 1.125rem;
  line-height: 1.78;
}

.diary-page .diary-prose h3 {
  font-weight: 700;
  letter-spacing: 0.12em;
  color: var(--ink);
  padding-bottom: 0.35rem;
  border-bottom: 1px solid color-mix(in srgb, var(--rule) 70%, transparent);
  display: inline-block;
}

.diary-page .diary-prose h4 {
  font-weight: 650;
}

.diary-page .diary-prose blockquote {
  border-left-color: var(--accent);
  background: color-mix(in srgb, var(--paper-alt) 60%, var(--paper) 40%);
  padding: 0.75rem 1.25rem;
  border-left-width: 3px;
  font-style: normal;
}

.diary-page .diary-prose strong {
  font-weight: 700;
}

.diary-page .diary-prose ul > li::before {
  width: 0.5rem;
  height: 2px;
  background: var(--accent);
  opacity: 0.8;
}

.diary-page .diary-prose ol > li::marker {
  font-family: var(--ff-plex-mono), ui-monospace, monospace;
  font-weight: 600;
  font-size: 0.8em;
}

.diary-page .diary-prose pre {
  background: var(--paper-alt);
  border-left: 3px solid var(--accent);
}

.diary-page .diary-section:first-child .diary-prose > p:first-of-type::first-letter {
  font-family: var(--font-display);
  font-size: 4.2em;
  color: var(--accent);
  margin-top: 0.08em;
}

.diary-page .diary-footer {
  position: relative;
}

.diary-page .diary-footer::before {
  content: "";
  position: absolute;
  top: -1px;
  left: 0;
  right: 0;
  height: 1px;
  background: linear-gradient(90deg, var(--accent) 0%, var(--accent) 96px, var(--rule) 96px, var(--rule) 100%);
}

.diary-page .diary-footer a {
  font-weight: 650;
}

@media (min-width: 1024px) {
  .diary-page .diary-hero-inner {
    padding-top: 3rem;
    padding-bottom: 4.5rem;
  }

  .diary-page .diary-toc {
    top: 1.5rem;
  }

  .diary-page .diary-toc-link {
    padding-block: 0.55rem;
  }

  .diary-page .diary-section {
    padding-block: 3.5rem;
  }
}

.diary-page .diary-toc-top {
  border: 1px solid var(--rule);
  padding: 0.35rem 0.75rem;
  border-radius: 2px;
  font-size: 0.8rem;
  font-weight: 600;
  letter-spacing: 0.02em;
  transition: border-color 180ms ease, color 180ms ease;
}

.diary-page .diary-toc-top:hover {
  border-color: var(--accent);
  color: var(--accent);
}

@media (min-width: 1024px) {
  .diary-page .diary-toc-top {
    border: 0;
    padding: 0;
    border-radius: 0;
    margin-top: 1.75rem;
    font-size: 0.875rem;
  }
}

.diary-page .diary-prose a {
  color: var(--accent);
  text-decoration: underline;
  text-underline-offset: 2px;
  text-decoration-thickness: 1px;
}

.diary-page .diary-prose a:hover {
  color: var(--ink);
}

@media (max-width: 1023px) {
  .diary-page .diary-toc {
    background: var(--paper);
    box-shadow: 0 1px 0 var(--rule);
  }
}
